  AddObjectOperation,
  ApplyPlanRequest,
  ConstraintSpec,
  EditableObjectClass,
  EntityId,
  FixedElement,
  LockEntityOperation,
  MaterialState,
  MoveObjectOperation,
  ObjectClass,
  ObjectMobility,
  OBB3D,
  Opening,
  OperationPlanPreview,
  Point2D,
  Point3D,
  Polygon2D,
  Pose3D,
  ReasonCode,
  RepaintSurfaceOperation,
