function extractSceneId(pathname: string): string | null {
  const patterns = [
    /^\/scenes\/([^/]+)$/,
    /^\/scenes\/([^/]+)\/quick-render$/,
    /^\/scenes\/([^/]+)\/preview$/,
    /^\/scenes\/([^/]+)\/apply$/,
    /^\/scenes\/([^/]+)\/undo$/,
  ];
  for (const pattern of patterns) {
    const match = pathname.match(pattern);
    if (match) {
      return decodeURIComponent(match[1]);
    }
  }
  return null;
}

