{"command":"set -euo pipefail
storage=$(mktemp -d)
api_log=$(mktemp)
PORT=3510 ROOMVIEW_API_STORAGE_DIRECTORY="$storage" ROOMVIEW_TOKEN_SECRET=test-secret npx --yes tsx ./apps/api/src/server.ts >"$api_log" 2>&1 &
api_pid=$!
cleanup(){ kill $api_pid >/dev/null 2>&1 || true; wait $api_pid >/dev/null 2>&1 || true; rm -rf "$storage" "$api_log"; }
trap cleanup EXIT
for i in $(seq 1 40); do if grep -q "RoomPlan API listening" "$api_log"; then break; fi; sleep 0.25; done
capture=$(curl -sS -X POST http://127.0.0.1:3510/captures/roomplan -H 'Content-Type: application/json' --data-binary @fixtures/roomplan/bedroom-primary/capture-request.json)
scene_id=$(printf '%s' "$capture" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).scene_id')
qr=$(printf '%s' "$capture" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).qr_payload')
token=$(printf '%s' "$qr" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).handoff_token')
redeem=$(curl -sS -X POST http://127.0.0.1:3510/handoffs/redeem -H 'Content-Type: application/json' -d '{"handoff_token":"'"$token"'"}')
session_id=$(printf '%s' "$redeem" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).session_id')
scene=$(curl -sS http://127.0.0.1:3510/scenes/$scene_id -H "Authorization: Bearer $session_id")
bookmark_pose=$(printf '%s' "$scene" | node -pe 'JSON.stringify(JSON.parse(require("fs").readFileSync(0,"utf8")).scene.bookmarks[0].camera_pose)')
bookmark_fov=$(printf '%s' "$scene" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).scene.bookmarks[0].fov')
bookmark=$(curl -sS -X POST http://127.0.0.1:3510/scenes/$scene_id/bookmarks -H 'Content-Type: application/json' -H "Authorization: Bearer $session_id" -d '{"name":"Smoke bookmark","camera_pose":'"$bookmark_pose"',"fov":'"$bookmark_fov"'}')
bookmark_id=$(printf '%s' "$bookmark" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).bookmark.bookmark_id')
snapshot_id=$(printf '%s' "$scene" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).scene.snapshot.snapshot_id')
photoreal=$(curl -sS -X POST http://127.0.0.1:3510/scenes/$scene_id/photoreal -H 'Content-Type: application/json' -H "Authorization: Bearer $session_id" -d '{"scene_snapshot_id":"'"$snapshot_id"'","bookmark_id":"'"$bookmark_id"'","prompt_modifiers":[],"idempotency_key":"smoke-photoreal"}')
job_id=$(printf '%s' "$photoreal" | node -pe 'JSON.parse(require("fs").readFileSync(0,"utf8")).job_id')
job=$(curl -sS http://127.0.0.1:3510/jobs/$job_id -H "Authorization: Bearer $session_id")
node - <<'EOF' "$bookmark" "$photoreal" "$job" "$snapshot_id"
const [bookmarkRaw, photorealRaw, jobRaw, snapshotId] = process.argv.slice(2);
const bookmark = JSON.parse(bookmarkRaw);
const photoreal = JSON.parse(photorealRaw);
const job = JSON.parse(jobRaw);
if (!bookmark.scene.bookmarks.some(b => b.bookmark_id === bookmark.bookmark.bookmark_id)) throw new Error('bookmark not in scene');
if (photoreal.photoreal_entry.scene_snapshot_id !== snapshotId) throw new Error('snapshot mismatch');
if (job.job.status !== 'ready') throw new Error('job not ready');
if (job.photoreal_entry?.entry_id !== photoreal.photoreal_entry.entry_id) throw new Error('job entry mismatch');
console.log('photoreal api smoke ok');
EOF","timeout":180}
